codeExample.bad:
// Single-letter shortcut active everywhere on the page, all the time,
// with no way to turn it off or remap it
document.addEventListener('keydown', (event) => {
  if (event.key === 's') {
    openSearchPanel();
  }
});

codeExample.good:
// Option 1: only active while a specific region has focus
searchRegion.addEventListener('keydown', (event) => {
  if (event.key === 's') {
    openSearchPanel();
  }
});

// Option 2: require a modifier key, and let the letter-only version
// be turned off in settings
const singleKeyShortcutsEnabled = getUserSetting('singleKeyShortcuts');
document.addEventListener('keydown', (event) => {
  const isShortcut = event.ctrlKey ? event.key === 's' :
    singleKeyShortcutsEnabled && event.key === 's';
  if (isShortcut) {
    event.preventDefault();
    openSearchPanel();
  }
});
